window.MOTIF_CATALOG_CHUNKS[56]={"cards":[{"id":"MEJE-KW-003385","row_version":1,"title":"담요와 베개로 만든 비밀 공간","original":"Blanket Fort","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"담요와 쿠션을 겹쳐 작은 임시 방을 만든다. 허술한 구조도 그 안에서는 놀이와 대화의 안전한 경계가 된다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-003385/index.html"},{"id":"MEJE-KW-003386","row_version":1,"title":"한 이불을 서로 끌어당기기","original":"Blanket Tug O' War","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"함께 자는 두 사람이 잠결에 이불을 자기 쪽으로 끌어당긴다. 작은 몸짓이 친밀함과 사소한 불편을 동시에 보여 준다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-003386/index.html"},{"id":"MEJE-KW-003387","row_version":1,"title":"경험과 신념이 없는 빈 인물","original":"Blank Slate","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"기억이나 삶의 경험이 거의 없이 만들어진 인물이 주변의 말에 따라 자신을 구성한다. 빈 상태를 성장의 가능성뿐 아니라 조종당할 위험으로도 본다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003387/index.html"},{"id":"MEJE-KW-003388","row_version":2,"title":"아무 반응 없는 멍한 시선","original":"Blank Stare","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"인물이 상대의 말이나 사건에 한동안 표정을 바꾸지 않고 바라본다. 감정이 없는지 표현을 미루는지는 장면의 맥락에서 드러난다. 시선의 감정 표현을 더 과장하면 눈동자가 사라진 흰 눈처럼 눈의 모양 자체가 달라진다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003388/index.html"},{"id":"MEJE-KW-003389","row_version":2,"title":"눈동자가 사라진 흰 눈","original":"Blank White Eyes","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"인물의 눈을 흰 원으로 단순화해 큰 충격이나 실신을 표현한다. 실제 신체 상태보다 만화적 감정 기호에 가깝다. 아무 반응 없는 멍한 시선보다 그림의 변화가 크지만 반응을 짧게 보여 준다는 점은 같다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003389/index.html"},{"id":"MEJE-KW-003390","row_version":1,"title":"끝없이 펼쳐진 흰 공간","original":"Blank White Void","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"벽과 수평선이 보이지 않는 하얀 공간에 인물이 놓인다. 비어 있는 풍경이 감금이나 사유, 세계 사이의 경계를 표현한다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-003390/index.html"},{"id":"MEJE-KW-003391","row_version":2,"title":"신보다 자신이 높다고 주장하기","original":"Blasphemous Boast","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 신성한 존재보다 자신이 뛰어나다고 선언한다. 그 말이 허세인지 실제 힘의 고백인지에 따라 주변의 반응이 달라진다. 자신을 높이는 말과 타인을 높이는 사람을 신에 빗대어 찬양하기의 화자를 구분한다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-003391/index.html"},{"id":"MEJE-KW-003392","row_version":2,"title":"사람을 신에 빗대어 찬양하기","original":"Blasphemous Praise","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"누군가를 찬양하면서 신성한 존재와 비교한다. 듣는 사람의 믿음과 관계에 따라 칭찬이 부담이나 모욕이 될 수도 있다. 말하는 사람이 자기 자신을 신과 비교하면 신보다 자신이 높다고 주장하기가 된다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-003392/index.html"},{"id":"MEJE-KW-003393","row_version":2,"title":"상대 손의 무기를 쏘아 떨어뜨리기","original":"Blasting It Out of Their Hands","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"총격으로 상대가 든 무기를 떨어뜨려 싸움을 멈춘다. 치명적 공격을 피하려는 의도와 장면의 과장된 정확도를 구분한다. 무기만 떨어뜨리려던 장면이 통제를 잃으면 한 발 뒤에 모두가 총을 쏘기으로 번질 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003393/index.html"},{"id":"MEJE-KW-003394","row_version":1,"title":"힘을 모아 크게 발사하기","original":"Blasting Time","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"인물이 팔과 몸을 크게 움직이며 에너지를 모았다가 한 번에 내보낸다. 발사 전의 자세가 공격의 규모를 예고한다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003394/index.html"},{"id":"MEJE-KW-003395","row_version":2,"title":"한 발 뒤에 모두가 총을 쏘기","original":"Blast Out","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"무장한 사람들이 팽팽히 대치하다 첫 총성이 나자 한꺼번에 사격한다. 누가 시작했는지보다 통제력을 잃은 집단의 반응이 장면을 지배한다. 일제 사격 대신 무장을 막는 한 발에 집중하면 상대 손의 무기를 쏘아 떨어뜨리기와 방향이 달라진다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003395/index.html"},{"id":"MEJE-KW-003396","row_version":1,"title":"담담하게 자기 힘 자랑하기","original":"Blasé Boast","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 놀랄 만한 능력을 평범한 사실처럼 말한다. 과장하지 않는 어조가 오히려 힘의 차이를 강조한다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-003396/index.html"},{"id":"MEJE-KW-003397","row_version":1,"title":"도둑임을 드러내는 차림새","original":"Blatant Burglar","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"가면과 줄무늬 옷, 큰 자루처럼 도둑을 알아보게 하는 시각 기호를 한 인물에게 모은다. 실제 은밀함보다 관객에게 역할을 즉시 알려 주는 디자인이다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003397/index.html"},{"id":"MEJE-KW-003398","row_version":2,"title":"이유 없이 놓인 게임 보급품","original":"Blatant Item Placement","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"세계의 상황으로 설명되지 않는 곳에 탄약이나 회복 물품이 놓여 있다. 플레이어의 진행을 돕는 배치가 장소의 설득력과 부딪힌다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-003398/index.html"},{"id":"MEJE-KW-003399","row_version":1,"title":"누가 봐도 거짓인 변명","original":"Blatant Lies","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 눈앞의 증거와 맞지 않는 설명을 끝까지 우긴다. 들키지 않을 기대보다 인정하기 싫은 마음이 말에 드러난다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-003399/index.html"},{"id":"MEJE-KW-003400","row_version":1,"title":"처음부터 실패할 계획","original":"Blatantly Self-Defeating","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"인물의 계획에 스스로 만든 모순이 있어 성공하기 어렵다는 사실을 관객이 먼저 안다. 외부 방해 없이도 무너질 이유가 전개의 긴장을 만든다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-003400/index.html"},{"id":"MEJE-KW-003401","row_version":3,"title":"흑인 액션영화의 역사적 장르","original":"Blaxploitation","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03"],"summary":"흑인 주인공과 도시의 권력 갈등을 전면에 세운 액션영화의 한 흐름. 그 시대의 표현과 관객층, 상업적 이용에 대한 비판을 함께 살핀다. 이 장르의 익숙한 표현을 다시 비틀면 흑인 액션영화 관습의 패러디가 된다.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"분류축","entry_url":"cards/MEJE-KW-003401/index.html"},{"id":"MEJE-KW-003402","row_version":2,"title":"흑인 액션영화 관습의 패러디","original":"Blaxploitation Parody","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"옛 흑인 액션영화의 의상과 음악, 영웅의 태도를 의식적으로 과장해 웃음을 만든다. 장르를 향한 애정과 그 안의 고정관념을 다루는 방식이 함께 드러난다. 원래 장르인 흑인 액션영화의 역사적 장르의 관습을 알수록 풍자의 대상이 분명해진다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-003402/index.html"},{"id":"MEJE-KW-003403","row_version":1,"title":"불을 뿜을 듯 매운 소스","original":"Blazing Inferno Hellfire Sauce","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"소스의 매운맛을 빛이나 열기까지 내는 위험한 물건처럼 과장한다. 식사라는 일상 행위를 환상적 소동으로 바꾼다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-003403/index.html"},{"id":"MEJE-KW-003404","row_version":1,"title":"돌봄을 잃은 암울한 요양 시설","original":"Bleak Abyss Retirement Home","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"돌봄 시설이 거주자의 선택과 존엄을 무시하는 장소로 그려진다. 시설의 존재 자체보다 운영 방식과 권력 관계를 문제로 다룬다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-003404/index.html"},{"id":"MEJE-KW-003405","row_version":1,"title":"외딴 국경의 황량한 기지","original":"Bleak Border Base","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"큰 사회에서 멀리 떨어진 전초기지에 인물이 배치된다. 고립과 부족한 자원이 일상의 관계와 판단을 바꾼다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-003405/index.html"},{"id":"MEJE-KW-003406","row_version":2,"title":"분위기가 갑자기 어두워지는 게임 구역","original":"Bleak Level","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"밝게 진행되던 게임이 한 구역에서 색과 소리, 이야기를 무겁게 바꾼다. 플레이어가 새로운 위험과 감정의 규칙을 체감한다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-003406/index.html"},{"id":"MEJE-KW-003407","row_version":1,"title":"상대를 해친 뒤 무게를 느끼기","original":"Bleed 'Em and Weep","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"위협을 막으려 폭력을 쓴 인물이 곧 자신의 행동에 충격을 받는다. 필요한 선택이었다고 해도 감정적 결과가 남는다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-003407/index.html"},{"id":"MEJE-KW-003408","row_version":1,"title":"효과가 없는 어설픈 검열","original":"*Bleep*-dammit!","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"화면과 소리를 가렸는데도 무엇을 숨기려 했는지 쉽게 드러난다. 검열의 빈틈이 의도하지 않은 웃음이나 비판을 만든다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-003408/index.html"},{"id":"MEJE-KW-003409","row_version":3,"title":"상처와 함께 아름답게 그려진 인물","original":"Blemished Beauty","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"흉터나 신체 차이가 있는 인물을 아름다움과 매력을 지닌 사람으로 그린다. 그 특징을 결함이나 극복 서사의 재료로만 줄이지 않는다. 외모에 대한 타인의 판단이 관계를 가로막는다는 점에서 외모의 편견을 넘어 만나는 두 사람와 만난다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003409/index.html"},{"id":"MEJE-KW-003410","row_version":1,"title":"여러 동물 특징이 섞인 수인","original":"Blended Beastfolk","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"한 동물 종만 닮지 않고 여러 종의 특징을 함께 지닌 존재. 몸의 모습뿐 아니라 종족의 생활과 관계도 독립적으로 설정한다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-003410/index.html"},{"id":"MEJE-KW-003411","row_version":3,"title":"두 가족이 합쳐지며 겪는 변화","original":"Blended Family Drama","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"새로 가족이 된 부모와 자녀들이 생활 방식과 거리감을 조정한다. 친밀함을 강요하기보다 각자의 관계가 쌓이는 시간을 보여 준다. 새 가족이 한 사람을 밀어내면 집단에서 배척당하는 가족 구성원의 위치가 생길 수 있다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-003411/index.html"},{"id":"MEJE-KW-003412","row_version":3,"title":"군중 속 한 사람처럼 섞여 숨기","original":"Blending-In Stealth Gameplay","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"플레이어가 눈에 띄지 않는 행동을 골라 주변 사람들 사이에 섞인다. 그림자에 숨는 대신 사회적 행동을 흉내 내는 잠입 규칙이다. 군중에 어울리는 잠입을 행사장에서 펼치면 격식 있는 행사에 손님으로 잠입하기의 장면이 된다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-003412/index.html"},{"id":"MEJE-KW-003413","row_version":2,"title":"선물처럼 보이지만 불편한 능력","original":"Blessed with Suck","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"특별한 능력이 주어졌지만 사용 조건이나 부작용이 인물의 삶을 어렵게 한다. 힘의 유용함과 감당할 대가가 함께 설정된다. 초월적 존재가 내리는 축복이 주는 힘이 언제나 당사자에게 이롭지는 않다는 경우다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-003413/index.html"},{"id":"MEJE-KW-003414","row_version":2,"title":"초월적 존재가 내리는 축복","original":"Blessing","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"초월적 존재가 한 사람에게 보호나 능력을 준다. 축복의 내용과 지속 조건, 주는 이와 받는 이의 관계가 세계의 규칙이 된다. 능력에 불편한 대가가 붙으면 선물처럼 보이지만 불편한 능력으로 보이기도 한다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-003414/index.html"},{"id":"MEJE-KW-003415","row_version":1,"title":"쫓는 사람이 지나치기 쉬운 골목에 숨기","original":"Blind Alley","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"도망치던 인물이 옆 골목으로 빠져 추격자가 그대로 지나가게 한다. 잠깐 보이지 않은 동선이 탈출의 기회를 만든다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003415/index.html"},{"id":"MEJE-KW-003416","row_version":2,"title":"외모의 편견을 넘어 만나는 두 사람","original":"Blind and the Beast","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"외모 때문에 소외된 사람과 시각장애가 있는 사람이 관계를 맺는다. 시각장애를 타인의 내면을 자동으로 알아보는 능력으로 만들지 않고 두 사람의 선택을 보여 준다. 외모를 단순한 결함으로 보지 않는 표현은 상처와 함께 아름답게 그려진 인물와도 연결된다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-003416/index.html"},{"id":"MEJE-KW-003417","row_version":1,"title":"내용을 열어 봐야 아는 수집 장난감","original":"Blind Bag Collectables","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"포장을 뜯기 전에는 어떤 장난감이 들었는지 알 수 없는 상품. 놀라움과 수집의 욕구가 구매 경험을 구성한다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-003417/index.html"},{"id":"MEJE-KW-003418","row_version":1,"title":"박쥐는 앞을 보지 못한다는 묘사","original":"Blind Bats","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"작품이 박쥐를 보지 못하는 존재로 그려 소동을 만든다. 동물의 실제 능력과 표현에 쓰인 통념을 구분한다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-003418/index.html"},{"id":"MEJE-KW-003419","row_version":3,"title":"인종과 장애를 한 인물의 기호로 뭉치기","original":"Blind Black Guy","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"흑인 시각장애인 인물을 특정 음악가나 신비한 조언자의 익숙한 틀로만 묘사한다. 두 정체성이 인물의 성격과 삶 전체를 대신하지 않도록 살핀다. 시각장애인 인물을 음악가로만 떠올리는 관습은 시각장애가 있는 음악가의 묘사에서도 점검할 수 있다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-003419/index.html"},{"id":"MEJE-KW-003420","row_version":1,"title":"처음 만난 두 사람의 소개팅","original":"Blind Date","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"서로를 잘 모르는 두 사람이 제삼자의 소개나 약속으로 만난다. 만남의 어색함과 이후 관계의 가능성이 함께 열린다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-003420/index.html"},{"id":"MEJE-KW-003421","row_version":2,"title":"앞을 보지 못한 채 차를 운전하기","original":"Blind Driving","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 시야를 잃거나 눈을 가린 상황에서 차량을 움직여야 한다. 위험한 장면의 연출이므로 동행자의 안내와 결과를 서사 안에서 다룬다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003421/index.html"},{"id":"MEJE-KW-003422","row_version":1,"title":"분노 때문에 판단이 좁아지기","original":"Blinded by Rage","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"싸우는 인물이 화가 커질수록 상대의 움직임과 주변 상황을 놓친다. 힘이 세져 보이더라도 선택의 폭은 줄어든다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-003422/index.html"},{"id":"MEJE-KW-003423","row_version":3,"title":"강한 빛으로 상대의 시야 가리기","original":"Blinded by the Light","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 빛을 비춰 상대가 잠시 앞을 보기 어렵게 만든다. 짧은 시야의 변화가 도망이나 역전의 시간을 만든다. 카메라의 플래시를 광원으로 쓰면 카메라 플래시로 시야가 흐려지기의 장면이 된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003423/index.html"},{"id":"MEJE-KW-003424","row_version":1,"title":"태양을 바라본 뒤 시야 잃기","original":"Blinded by the Sun","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"작품 속 인물이 강한 햇빛을 직접 바라보다 앞이 흐려지는 일을 겪는다. 결과의 지속과 회복은 작품이 정한 장면의 조건으로 다룬다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003424/index.html"},{"id":"MEJE-KW-003425","row_version":1,"title":"행선지를 모른 채 눈가리고 이동하기","original":"Blindfolded Trip","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 목적지를 알지 못하도록 시야를 가린 채 이동한다. 도착 장소보다 누가 정보를 쥐고 있는지가 긴장을 만든다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003425/index.html"},{"id":"MEJE-KW-003426","row_version":1,"title":"눈을 가리고도 주변을 알아보기","original":"Blindfolded Vision","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"인물이 눈을 가린 상태에서도 다른 감각이나 특별한 힘으로 주변을 파악한다. 그 능력의 범위와 대가가 설정의 일부다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-003426/index.html"},{"id":"MEJE-KW-003427","row_version":1,"title":"뜻을 놓친 어색한 번역","original":"\"Blind Idiot\" Translation","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"번역문이 낱말을 옮겼지만 문장의 의도나 상황에 맞지 않아 엉뚱한 뜻이 된다. 오역이 정보 전달과 인물의 선택을 흔든다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-003427/index.html"},{"id":"MEJE-KW-003428","row_version":2,"title":"카메라 플래시로 시야가 흐려지기","original":"Blinding Camera Flash","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"사진을 찍는 순간의 강한 섬광에 인물이 잠깐 주변을 보기 어렵다. 평범한 기록 도구가 장면의 방해물이 된다. 사진기의 섬광을 전투에 이용하면 강한 빛으로 상대의 시야 가리기의 한 장면으로 볼 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003428/index.html"},{"id":"MEJE-KW-003429","row_version":2,"title":"계산 없이 감행하는 우주 도약","original":"Blind Jump","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"안전한 경로를 확인할 시간이 없어 인물이 우주선의 장거리 이동을 서둘러 시도한다. 기술의 한계와 긴급한 선택이 충돌한다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-003429/index.html"},{"id":"MEJE-KW-003430","row_version":2,"title":"눈가린 정의의 상징을 인물로 만들기","original":"Blind Justice","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"눈을 가린 정의의 이미지를 실제 인물의 외형이나 사명으로 드러낸다. 상징이 공정한 판단을 뜻하는지 인물의 한계를 드러내는지는 이야기에서 정한다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-003430/index.html"},{"id":"MEJE-KW-003431","row_version":1,"title":"시각 정보가 부족해 생기는 착오","original":"Blind Mistake","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 필요한 시각 정보를 얻지 못해 물건이나 장소를 잘못 짚는다. 개인의 능력만이 아니라 안내와 환경의 설계가 결과를 바꾼다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003431/index.html"},{"id":"MEJE-KW-003432","row_version":2,"title":"시각장애가 있는 음악가","original":"Blind Musician","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"시각장애가 있는 인물이 연주나 창작을 직업으로 삼는다. 음악적 능력을 장애가 준 신비한 보상으로 설명하지 않고 연습과 선택을 보여 준다. 음악가라는 역할 하나로 인물 전체를 정리하면 인종과 장애를 한 인물의 기호로 뭉치기의 단순화와 겹친다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003432/index.html"},{"id":"MEJE-KW-003433","row_version":1,"title":"권위자에게 질문 없이 따르기","original":"Blind Obedience","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"인물이 상관의 판단을 의심하지 않고 명령을 수행한다. 충성의 이유와 잘못된 명령을 만났을 때의 선택이 갈등이 된다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-003433/index.html"},{"id":"MEJE-KW-003434","row_version":2,"title":"시각장애인의 선글라스를 기호로 쓰기","original":"Blind People Wear Sunglasses","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"작품이 선글라스를 통해 인물의 시각장애를 빠르게 알린다. 실제 착용 이유와 개인 차이를 지우지 않는 묘사가 필요하다. 선글라스와 음악가 같은 표지를 한 인물에 몰아주면 인종과 장애를 한 인물의 기호로 뭉치기의 관습이 된다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-003434/index.html"},{"id":"MEJE-KW-003435","row_version":2,"title":"시각 없이 미래를 읽는 예언자","original":"Blind Seer","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"앞을 보지 못하는 인물이 예언이나 다른 감각으로 남들이 모르는 사실을 안다. 장애 자체를 신비한 능력의 원인으로 단정하지 않고 인물의 역할과 선택을 본다. 시각을 쓰지 않는 인물의 다른 역할로 시각 없이 싸우는 무기 달인를 함께 볼 수 있다. 예언과 전투의 능력은 각각 따로 설명해야 한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003435/index.html"},{"id":"MEJE-KW-003436","row_version":1,"title":"가치 없는 줄 알고 물건을 뒤로 던지기","original":"Blind Shoulder Toss","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 손에 든 물건을 잠깐 보고 쓸모없다며 뒤로 던진다. 그것이 나중에 중요한 물건으로 드러나면 판단의 성급함이 웃음이나 사건을 만든다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003436/index.html"},{"id":"MEJE-KW-003437","row_version":1,"title":"시각 없이 싸우는 무기 달인","original":"Blind Weaponmaster","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"보지 못하는 무기 사용자가 다른 감각이나 훈련으로 전투를 이끈다. 실력의 근거를 보여 주면서 시각 장애를 초능력과 동일시하지 않는다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003437/index.html"},{"id":"MEJE-KW-003438","row_version":1,"title":"안경을 벗자 아무것도 못 보는 인물","original":"Blind Without 'Em","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"평소 안경을 쓰던 인물이 그것을 잃자 눈앞의 일을 거의 알아보지 못한다. 시력의 차이를 한순간의 소동을 만드는 장치로 과장한 표현이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003438/index.html"},{"id":"MEJE-KW-003439","row_version":2,"title":"보석으로 꾸민 무기","original":"Bling-Bling-BANG!","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"무기에 금속 장식이나 보석을 붙여 성능보다 소유자의 부와 취향을 드러낸다. 화려함이 위세가 될 수도 실전의 불편함이 될 수도 있다. 무기의 화려함이 복장까지 이어지면 전투복보다 화려한 군복와 닮은 과시가 된다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-003439/index.html"},{"id":"MEJE-KW-003440","row_version":1,"title":"전투복보다 화려한 군복","original":"Bling of War","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"전장에서 입는 옷을 의례용처럼 빛나고 장식적으로 만든다. 군의 위엄을 보여 주지만 실제 전투 환경과의 어긋남도 생긴다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003440/index.html"},{"id":"MEJE-KW-003441","row_version":1,"title":"승리를 알리는 번쩍이는 조명","original":"Blinking Lights of Victory","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"승부나 경품의 결과가 확정되는 순간 불빛을 빠르게 켜고 끈다. 작은 결과도 무대의 큰 사건처럼 느끼게 하는 시각 신호다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-003441/index.html"},{"id":"MEJE-KW-003442","row_version":1,"title":"짧은 영상 조각의 빠른 연속","original":"Blipvert","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"서로 다른 이미지를 아주 짧게 이어 붙여 관객에게 강한 인상을 남긴다. 이해할 시간을 줄이는 편집이 흥분이나 혼란을 만든다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-003442/index.html"},{"id":"MEJE-KW-003443","row_version":1,"title":"힘든 과거를 아무렇지 않게 말하기","original":"Blissfully Horrific Backstory","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"청자가 충격을 받을 만한 경험을 인물은 평범한 추억처럼 이야기한다. 말하는 사람과 듣는 사람이 사건의 무게를 다르게 느끼는 간격이 드러난다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-003443/index.html"},{"id":"MEJE-KW-003444","row_version":2,"title":"낯선 공동체를 흔드는 밝은 방문자","original":"Blithe Spirit","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"엄격한 분위기의 공동체에 자유로운 인물이 들어와 오래된 규칙을 질문한다. 활기가 변화를 만들더라도 기존 사람들의 이유를 모두 지우지는 않는다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003444/index.html"},{"id":"MEJE-KW-003445","row_version":1,"title":"공습을 피해 낯선 집으로 보내진 아이","original":"Blitz Evacuees","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"전쟁 중 도시의 아이가 폭격을 피해 다른 지역의 집에서 지낸다. 안전을 위한 이동이 가족과의 분리, 새 관계의 시작이 된다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-003445/index.html"},{"id":"MEJE-KW-003446","row_version":1,"title":"형태가 일정하지 않은 괴물","original":"Blob Monster","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"몸의 윤곽이 흐르고 흘러내리거나 다시 뭉치는 존재가 나타난다. 고정된 얼굴과 팔다리가 없다는 점이 움직임과 위협의 규칙을 바꾼다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-003446/index.html"},{"id":"MEJE-KW-003447","row_version":1,"title":"막기만 하면 피해를 전혀 받지 않는 규칙","original":"Blocking Stops All Damage","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"공격의 크기와 종류에 관계없이 막기 동작이 성공하면 피해가 사라진다. 방어의 타이밍이 세계의 물리적 결과보다 중요한 게임 규칙이다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-003447/index.html"},{"id":"MEJE-KW-003448","row_version":2,"title":"상자를 밀어 길을 여는 퍼즐","original":"Block Puzzle","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"플레이어가 상자나 돌을 옮겨 통로와 발판을 만든다. 물건의 위치를 바꾸는 순서가 공간을 푸는 열쇠다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-003448/index.html"},{"id":"MEJE-KW-003449","row_version":2,"title":"다른 사람을 겨눠 위협을 뒤집는 악역","original":"Blofeld Ploy","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"악역이 주인공을 해칠 듯하다가 갑자기 옆의 부하나 다른 인물을 공격한다. 예상한 표적을 바꿔 권력과 변덕을 드러내는 장면이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003449/index.html"},{"id":"MEJE-KW-003450","row_version":1,"title":"개인 기록을 연재하는 웹 공간","original":"Blog","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":null,"parent_id":null,"tag_path":["ML-F02"],"summary":"한 사람이 글과 사진을 시간 순서로 올려 생각이나 활동을 기록하는 웹 형식. 독자가 댓글과 링크로 이어질 수 있어 개인의 기록이 공개 대화가 된다.","accent":"#55758A","tab":"#9A6A55","facet":"미디어","bookmark":"분류축","entry_url":"cards/MEJE-KW-003450/index.html"},{"id":"MEJE-KW-003451","row_version":2,"title":"세 가지 머리색으로 짝지은 여성 셋","original":"Blonde, Brunette, Redhead","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"서로 다른 머리색의 여성 세 명을 한 화면에 배치해 곧바로 구별되게 한다. 색의 대비가 성격이나 역할까지 정한다는 뜻은 아니다. 머리색에 인물의 역할을 기대하는 관습은 보수 성향의 금발 미인이라는 인물 틀에서도 드러나지만 정치 성향의 추측에는 주의가 필요하다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003451/index.html"},{"id":"MEJE-KW-003452","row_version":1,"title":"보수 성향의 금발 미인이라는 인물 틀","original":"Blonde Republican Sex Kitten","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"외모와 정치 성향의 조합만으로 인물을 의외의 존재처럼 소개한다. 취향과 신념을 머리색이나 성별에 묶는 고정관념을 돌아보게 한다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-003452/index.html"},{"id":"MEJE-KW-003453","row_version":3,"title":"피에 몸을 담그는 인물","original":"Blood Bath","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"인물이 피로 채운 욕조에 들어가는 장면으로 위험한 욕망이나 초자연적 의례를 암시한다. 실제 효능보다 피를 생명력의 상징으로 보는 믿음이 중요하다. 피를 젊음이나 권력의 상징으로 삼는 피에 집착하는 귀족 여성 악역의 장면과 연결된다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-003453/index.html"},{"id":"MEJE-KW-003454","row_version":1,"title":"대량 살해를 악역의 기원으로 쓰기","original":"Bloodbath Villain Origin","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"한 인물이 과거의 단일한 참극을 저지른 뒤 악역으로 소개된다. 사건의 규모만으로 인물의 동기를 설명했다고 여기지 않도록 한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003454/index.html"},{"id":"MEJE-KW-003455","row_version":1,"title":"피에 집착하는 귀족 여성 악역","original":"Blood Countess","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"부와 권력을 가진 여성 악역이 피를 젊음이나 지배의 수단으로 여긴다. 역사 인물에 대한 전설과 작품의 허구를 구분해 읽는다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003455/index.html"},{"id":"MEJE-KW-003456","row_version":2,"title":"피와 유해를 섞어 만든 건축물","original":"Blood for Mortar","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"건물의 재료에 사람의 피나 유해가 들어갔다고 설정해 장소의 폭력적 과거를 드러낸다. 벽이 사건을 숨기면서도 증언하는 이미지가 된다. 몸의 재료가 공간 전체로 커지면 살아 있는 몸처럼 보이는 지옥처럼 장소 자체가 위협이 된다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-003456/index.html"},{"id":"MEJE-KW-003457","row_version":2,"title":"온몸에서 피가 나는 과장된 장면","original":"Blood from Every Orifice","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"여러 곳에서 피가 동시에 보이게 해 인물의 위기를 한눈에 강조한다. 실제 증상에 대한 설명보다 극단적인 상태를 알리는 화면의 기호다. 한 곳의 출혈을 알리는 입가에 피가 번지는 위기의 표지보다 위기를 훨씬 넓은 몸의 표면에 나타낸다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003457/index.html"},{"id":"MEJE-KW-003458","row_version":1,"title":"입가에 피가 번지는 위기의 표지","original":"Blood from the Mouth","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"인물이 입에서 피를 흘리며 몸에 큰 일이 생겼음을 알린다. 화면의 흔한 신호이지만 실제 상태의 원인을 하나로 단정하지 않는다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003458/index.html"},{"id":"MEJE-KW-003459","row_version":2,"title":"이전보다 잔혹해진 후속작","original":"Bloodier and Gorier","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"같은 시리즈의 새 편이 앞선 작품보다 피와 상처를 더 직접적으로 보여 준다. 이야기의 변화인지 관객을 놀라게 하려는 표현 변화인지 따져 볼 수 있다. 앞선 편의 상처가 보이지 않는 격렬한 폭력를 벗어나 상처를 더 직접적으로 보여 주는 변화일 수 있다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-003459/index.html"},{"id":"MEJE-KW-003460","row_version":2,"title":"피에서 얻은 쇠로 만든 물건","original":"Blood Iron","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"작품이 생명체의 피를 금속 재료의 원천으로 삼아 물건을 만든다. 재료의 희소성과 그 대가가 물건에 불길한 뜻을 더한다. 피를 재료로 쓴다는 점에서 피와 유해를 섞어 만든 건축물의 건축과 비슷한 대가를 묻게 된다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-003460/index.html"},{"id":"MEJE-KW-003461","row_version":1,"title":"물속으로 번지는 피","original":"Blood Is Squicker in Water","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"물속에 나온 피가 넓게 퍼져 실제보다 큰 위험처럼 보인다. 맑은 공간이 붉게 변하는 모습이 충격을 만든다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-003461/index.html"},{"id":"MEJE-KW-003462","row_version":1,"title":"피 묻은 몸을 개의치 않는 인물","original":"Blood Is the New Black","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"인물이 피가 튄 옷과 얼굴을 닦지 않은 채 계속 움직인다. 무감각이나 흥분, 지친 상태 중 무엇인지 행동의 맥락이 정한다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003462/index.html"},{"id":"MEJE-KW-003463","row_version":2,"title":"싸움 자체를 원하는 전투광","original":"Blood Knight","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"인물이 승리나 명분보다 강한 상대와 겨루는 경험을 좇는다. 같은 충동도 영웅의 위험 감수와 악역의 폭력으로 다르게 이어질 수 있다. 싸움에서 다친 순간 자기 피를 보고 강해지는 인물처럼 더 강하게 반응할 수도 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-003463/index.html"},{"id":"MEJE-KW-003464","row_version":1,"title":"상처가 보이지 않는 격렬한 폭력","original":"Bloodless Carnage","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"큰 충돌이 있었는데 화면에는 피와 상처가 거의 남지 않는다. 폭력의 결과를 덜 보이게 하는 표현 선택이 장면의 무게를 바꾼다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003464/index.html"},{"id":"MEJE-KW-003465","row_version":1,"title":"피를 보거나 마시는 일에 끌리는 인물","original":"Bloodlust","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"인물이 피 자체에 강한 관심을 보이며 말이나 행동으로 드러낸다. 그 관심만으로 실제 폭력성을 단정하지 않고 작품 안의 선택을 본다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-003465/index.html"},{"id":"MEJE-KW-003466","row_version":2,"title":"피로 맺었다고 여기는 맹세","original":"Blood Oath","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"당사자들이 피를 약속의 표지로 삼아 관계를 묶는다. 실제 절차보다 약속을 어겼을 때 공동체가 부여하는 의미가 중요하다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-003466/index.html"},{"id":"MEJE-KW-003467","row_version":1,"title":"토론장 안에서 벌어지는 난투","original":"Blood on the Debate Floor","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"의견을 겨루던 공적 회의가 몸싸움으로 번진다. 말로 정해야 할 결정을 힘으로 밀어붙이는 순간 제도의 권위가 흔들린다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003467/index.html"},{"id":"MEJE-KW-003468","row_version":2,"title":"남의 피가 묻은 무고한 인물","original":"Blood-Splattered Innocents","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"폭력의 현장에 있던 인물에게 다른 사람의 피가 튄다. 피해의 충격과 타인의 오해가 한 화면에 겹친다. 같이 피가 묻어도 피투성이가 된 전투 인물와 달리 전투의 주체가 아닐 수 있다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003468/index.html"},{"id":"MEJE-KW-003469","row_version":1,"title":"피투성이가 된 전투 인물","original":"Blood-Splattered Warrior","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"전투를 마친 인물의 몸과 옷에 피가 남는다. 그것이 자신의 상처인지 다른 이의 피인지에 따라 장면의 뜻이 달라진다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003469/index.html"},{"id":"MEJE-KW-003470","row_version":1,"title":"피 묻은 웨딩드레스","original":"Blood-Splattered Wedding Dress","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"축하의 옷에 피가 묻어 결혼식의 약속과 폭력의 결과가 한 이미지에 겹친다. 누가 입었고 무슨 일이 있었는지에 따라 상징이 바뀐다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-003470/index.html"},{"id":"MEJE-KW-003471","row_version":2,"title":"치명적인 경기를 관람거리로 삼는 사회","original":"Blood Sport","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"참가자가 크게 다치거나 죽을 수 있는 경기를 대중 오락으로 운영한다. 관중의 열광과 선수의 선택권이 그 사회의 가치를 드러낸다. 경기에 자원한 싸움 자체를 원하는 전투광라도 관람을 위해 설계된 위험을 모두 통제할 수 있는 것은 아니다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-003471/index.html"},{"id":"MEJE-KW-003472","row_version":1,"title":"첫 성관계의 피를 순결 증거로 삼기","original":"Bloodstained Defloration","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"작품 속 인물들이 침구의 피를 성 경험 여부의 증거로 요구한다. 몸에 대한 잘못된 믿음이 통제와 압박의 도구가 되는 재현이다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-003472/index.html"},{"id":"MEJE-KW-003473","row_version":1,"title":"예배당의 유리창 앞에서 싸우기","original":"Blood-Stained Glass Windows","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"종교적 공간의 색유리와 빛을 배경으로 격렬한 충돌을 보여 준다. 장소가 약속하는 평온과 벌어지는 폭력의 차이가 이미지를 만든다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-003473/index.html"},{"id":"MEJE-KW-003474","row_version":2,"title":"피가 묻은 편지","original":"Blood-Stained Letter","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"글을 적은 종이에 피가 남아 문장 밖의 사건을 암시한다. 누가 썼고 언제 묻었는지가 수사의 단서가 될 수 있다. 종이에 남은 피와 피로 남은 손자국은 모두 현장에 없던 사건을 암시하는 흔적이다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-003474/index.html"},{"id":"MEJE-KW-003475","row_version":2,"title":"흡혈하는 박쥐의 대중 이미지","original":"Bloodsucking Bats","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"박쥐가 피를 마시는 존재로 그려져 흡혈귀의 분위기를 더한다. 다양한 박쥐를 하나의 위협으로 묶는 이미지와 실제 동물을 구분한다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-003475/index.html"},{"id":"MEJE-KW-003476","row_version":1,"title":"아스테카 문화를 피의 의례로만 그리기","original":"Bloodthirsty Aztecs","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 아스테카 문화를 희생 제의와 폭력의 모습으로만 압축한다. 한 사회의 다양한 생활과 역사를 지우는 고정관념임을 드러낸다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-003476/index.html"},{"id":"MEJE-KW-003477","row_version":1,"title":"수혈이 사건의 열쇠가 되는 이야기","original":"Blood Transfusion Plot","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"인물의 생존이나 관계가 필요한 피를 구하는 문제와 연결된다. 의료 절차를 단순화한 극적 장치인지 세계의 규칙인지 구분해 다룬다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-003477/index.html"},{"id":"MEJE-KW-003478","row_version":2,"title":"자기 피를 보고 강해지는 인물","original":"Blood Upgrade","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"상처에서 피가 난 것을 본 인물이 두려움 대신 더 큰 힘이나 집중을 얻는다. 반응이 타고난 능력인지 마음의 전환인지 작품이 정한다. 상처를 보고 강해진 반응이 피를 흘리면서 웃는 인물의 표정으로 나타날 수 있다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-003478/index.html"},{"id":"MEJE-KW-003479","row_version":1,"title":"살아 있는 몸처럼 보이는 지옥","original":"Bloody Bowels of Hell","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"지옥의 땅과 벽을 피와 살, 거대한 생체 기관 같은 모습으로 그린다. 장소 자체가 위협적인 존재처럼 느껴지는 환경이다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-003479/index.html"},{"id":"MEJE-KW-003480","row_version":4,"title":"죄책감이 피의 환영으로 나타나기","original":"Bloody Hallucinations of Guilt","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"어떤 죽음에 책임을 느끼는 인물이 실제로 없는 피를 보았다고 경험한다. 환영은 그 사람의 감정과 기억을 보여 주는 서사적 표현이다. 피로 남은 손자국이 실제 단서라면 이 장면의 피는 인물의 죄책감이 만든 지각이다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-003480/index.html"},{"id":"MEJE-KW-003481","row_version":1,"title":"피로 남은 손자국","original":"Bloody Handprint","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"벽이나 물건에 피 묻은 손의 흔적이 남아 현장에 있었던 사람의 움직임을 암시한다. 도움을 청한 표식인지 경고인지 추적이 필요하다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-003481/index.html"},{"id":"MEJE-KW-003482","row_version":2,"title":"피 튀는 장면을 우스꽝스럽게 만들기","original":"Bloody Hilarious","aliases":[],"kind":"keyword","facet_id":"ML-F19","node_kind":null,"parent_id":null,"tag_path":["ML-F19"],"summary":"과장된 출혈이 공포 대신 불합리한 웃음을 일으킨다. 피해를 어떻게 다루는지가 웃음의 방향을 정한다. 같은 피의 이미지가 피를 공포의 중심 이미지로 쓰기에서는 공포를 만드는 방향으로 쓰인다.","accent":"#9B7F74","tab":"#9A6A55","facet":"정서·톤","bookmark":"분류축","entry_url":"cards/MEJE-KW-003482/index.html"},{"id":"MEJE-KW-003483","row_version":2,"title":"피를 공포의 중심 이미지로 쓰기","original":"Bloody Horror","aliases":[],"kind":"keyword","facet_id":"ML-F19","node_kind":null,"parent_id":null,"tag_path":["ML-F19"],"summary":"피의 흔적이나 흐름을 보여 줘 아직 보이지 않는 위험을 느끼게 한다. 피의 양보다 그것이 나타난 장소와 시점이 긴장을 만든다. 출혈을 과장해 웃음으로 바꾸면 피 튀는 장면을 우스꽝스럽게 만들기와 방향이 갈라진다.","accent":"#9B7F74","tab":"#9A6A55","facet":"정서·톤","bookmark":"분류축","entry_url":"cards/MEJE-KW-003483/index.html"},{"id":"MEJE-KW-003484","row_version":2,"title":"피를 공격 수단으로 쓰는 능력","original":"Bloody Murder","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"인물이 피를 움직이거나 변형해 상대에게 맞서는 힘을 지닌다. 그 힘이 어디서 오고 누구에게 대가를 치르게 하는지 세계의 규칙이 된다. 자기 피를 보고 강해지는 인물는 자기 피를 본 뒤 강해지는 반응이고, 이 능력은 피 자체를 다루는 규칙이다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-003484/index.html"}]}.cards;